('oak',3,'英语','Yes. What do you want to do there?','["可以。你在那儿想做什么？"]',0,'可以。你在那儿想做什么？',1,0,1794557334,'ep-card-park-g3','日常口语','https://english.example.com/audio/ep/ep-card-park-g3/s002-n-484e9c.mp3'),
('oak',3,'英语','I want to swing and go down the slide.','["我想荡秋千，再滑滑梯。"]',0,'我想荡秋千，再滑滑梯。',1,0,1794557334,'ep-card-park-g3','日常口语','https://english.example.com/audio/ep/ep-card-park-g3/s003-n-1b0cb0.mp3'),
('oak',3,'英语','Sounds good. Please put on your shoes.','["好。请穿上鞋子。"]',0,'好。请穿上鞋子。',1,0,1794557334,'ep-card-park-g3','日常口语','https://english.example.com/audio/ep/ep-card-park-g3/s004-n-031bd2.mp3'),
('oak',3,'英语','I''m all set. Can Ben come with us?','["我准备好了。Ben 能和我们一起去吗？"]',0,'我准备好了。Ben 能和我们一起去吗？',1,0,1794557334,'ep-card-park-g3','日常口语','https://english.example.com/audio/ep/ep-card-park-g3/s005-n-701edb.mp3'),
