('oak',3,'英语','No problem. See you after class!','["没事。下课后见！"]',0,'没事。下课后见！',1,0,1794557334,'ep-card-polite-g3','日常口语','https://english.example.com/audio/ep/ep-card-polite-g3/s006-n-e3b4d7.mp3'),
