('oak',3,'英语','Hello and welcome back to Learning English with Minecraft.','["大家好，欢迎回到“用《我的世界》学英语”。"]',0,'大家好，欢迎回到“用《我的世界》学英语”。',1,0,1794557334,'ep-video-makingfriends-1','交朋友','https://english.example.com/audio/ep/ep-video-makingfriends-1/s001-n-e6a7e0.mp3'),
('oak',3,'英语','My name is Kenzo.','["我叫 Kenzo。"]',0,'我叫 Kenzo。',1,0,1794557334,'ep-video-makingfriends-1','交朋友','https://english.example.com/audio/ep/ep-video-makingfriends-1/s002-n-54da58.mp3'),
('oak',3,'英语','And in this series I teach English while playing Minecraft.','["在这个系列里，我一边玩《我的世界》一边教英语。"]',0,'在这个系列里，我一边玩《我的世界》一边教英语。',1,0,1794557334,'ep-video-makingfriends-1','交朋友','https://english.example.com/audio/ep/ep-video-makingfriends-1/s003-n-928f13.mp3'),
('oak',3,'英语','And it looks like there''s a zombie in our garden right here.','["看起来我们的菜园里有一只僵尸，就在这儿。"]',0,'看起来我们的菜园里有一只僵尸，就在这儿。',1,0,1794557334,'ep-video-makingfriends-1','交朋友','https://english.example.com/audio/ep/ep-video-makingfriends-1/s004-n-931415.mp3'),
('oak',3,'英语','Get out of my garden!','["从我的菜园里出去！"]',0,'从我的菜园里出去！',1,0,1794557334,'ep-video-makingfriends-1','交朋友','https://english.example.com/audio/ep/ep-video-makingfriends-1/s005-n-a1b37a.mp3'),
