('oak',3,'英语','This cave is scary.','["这个洞穴好可怕。"]',0,'这个洞穴好可怕。',1,0,1794557334,'ep-video-strikinggold-2','挖到金矿','https://english.example.com/audio/ep/ep-video-strikinggold-2/s001-n-6a8b59.mp3'),
('oak',3,'英语','There are monsters everywhere.','["到处都是怪物。"]',0,'到处都是怪物。',1,0,1794557334,'ep-video-strikinggold-2','挖到金矿','https://english.example.com/audio/ep/ep-video-strikinggold-2/s002-n-f4ff1d.mp3'),
